command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-5000 --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "git fetch failed" }

Write-Host "LOCAL_BRANCH=$(git branch --show-current)"
Write-Host "LOCAL_HEAD=$(git rev-parse HEAD)"
Write-Host "ORIGIN_MAIN=$(git rev-parse origin/main)"
Write-Host "TARGET=$(git rev-parse origin/work/large-folder-5000)"

$status = @(git status --short)
if ($status.Count -ne 0) {
  $status | ForEach-Object { Write-Host $_ }
  throw "persistent checkout has unexpected local changes"
}
if ((git rev-parse origin/main).Trim() -ne "a447073696959ac4460e28603f664aa953c403f1") {
  throw "main moved after large-folder snapshot"
}

if ((git branch --show-current) -ne "work/large-folder-5000") {
  if (git show-ref --verify --quiet refs/heads/work/large-folder-5000) {
    git checkout work/large-folder-5000
  } else {
    git checkout -b work/large-folder-5000 --track origin/work/large-folder-5000
  }
  if ($LASTEXITCODE -ne 0) { throw "cannot checkout large-folder branch" }
}
git merge --ff-only origin/work/large-folder-5000
if ($LASTEXITCODE -ne 0) { throw "cannot fast-forward large-folder branch" }

Write-Host "FOCUSED_SOURCE"
python -X utf8 -m unittest tests.winui.test_large_folder_contract tests.winui.test_validation_scope_contract
if ($LASTEXITCODE -ne 0) { throw "focused source contracts failed" }

Write-Host "RELEASE_BUILD"
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

Write-Host "HELPER_PROTOCOL"
python -X utf8 tests\winui\helper\test_process_isolation.py
if ($LASTEXITCODE -ne 0) { throw "helper protocol test failed" }

Write-Host "OWNED_5000_GUI"
python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 5000 --configuration Release
if ($LASTEXITCODE -ne 0) { throw "5000-file GUI test failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed" }

Write-Host "LARGE_FOLDER_5000_ACCEPTANCE_PASS"
